                Films?.Add(new Film { Name= "12 років рабства", FilmDirector="Стів МакКвін", Genre= "Біографічна драма/історичний фільм", Year=2013, Poster="12_років_рабства.jpg", Description= "Фільм заснований на реальних подіях і розповідає історію Соломона Нортапа — вільного чорношкірого чоловіка, який жив у штаті Нью-Йорк у 1841 році. Після виступу з музикантами в Вашингтоні його викрадають двоє чоловіків, накачують наркотиками та продають у рабство на південь США. Протягом дванадцяти років Соломон змушений терпіти жорстокі знущання та працювати на плантаціях Луїзіани, не втрачаючи при цьому людяності та сподівання знову побачити свою родину й повернути свободу." });
                Films?.Add(new Film { Name= "Книжкова злодійка", FilmDirector="Браян Персівал", Genre= "Військова драма/історичний фільм", Year=2013, Poster= "Книжкова_Злодійка.jpeg", Description= "Події фільму розгортаються у нацистській Німеччині під час Другої світової війни. Історія подається від імені Смерті. У центрі сюжету — маленька дівчинка Лізель, яку віддають на виховання до прийомної родини в Мюнхені. Новий батько вчить її читати, і це захоплення повністю змінює її життя. У світі, де панують цензура, страх і спалення забороненої літератури, Лізель починає красти книжки з бібліотеки бургомістра та ділитися ними з іншими. Тим часом її родина переховує в підвалі єврейського юнака Макса, що стає для дівчинки справжнім другом." });
                Films?.Add(new Film { Name="1+1", FilmDirector= "Олів'є Накаш, Ерік Толедано", Genre= "Комедія/драма/біографія", Year=2011, Poster= "1_1.jpg", Description= "Фільм заснований на реальних подіях і розповідає про несподівану дружбу двох абсолютно різних людей. Багатий аристократ Філіпп унаслідок нещасного випадку залишається паралізованим і прикутим до інвалідного візка. Шукаючи доглядальника, він наймає Дрісса — молодого чоловіка з передмістя, який щойно вийшов із в'язниці і зовсім не має досвіду такої роботи. Попри початковий шок та культурну прірву, безпосередність, почуття гумору й життєва енергія Дрісса повертають Філіппу смак до життя." });
                Films?.Add(new Film { Name = "Зелена миля", FilmDirector = "Франк Дарабонт", Genre = "Драма/Кримінал", Year = 1999, Poster = "Зелена_миля.jpg", Description= "Фільм знятий за однойменним романом Стівена Кінга та розповідає про події у блоці смертників федеральної в'язниці «Холодна гора». Головний наглядець цього блоку, Пол Еджкомб, бачив чимало злочинців за роки своєї роботи. Проте поява нового ув'язненого — величезного чорношкірого Джона Коффі, засудженого за жорстоке вбивство двох маленьких дівчаток — повністю змінює звичний уклад в'язниці. Попри свій страхітливий вигляд, Джон виявляється надзвичайно лагідною людиною з чистим серцем і дивовижними надприродними здібностями зцілювати людей. Це змушує наглядача по-новому подивитися на поняття справедливості, добра і зла." });
