                Films?.Add(new Film { Name= "Цілитель: Дочка Авіценни", FilmDirector= "Філіп Штельцль", Genre= "Драма/Романтика", Year=2013, Poster= "Лікар_Учень_Авіценни.jpeg", Description= "Події розгортаються в XI столітті. Головний герой — англійський хлопець Роб Коул. Після смерті матері від загадкової хвороби він залишається сиротою і приєднується до мандруватого цирульника-шарлатана, який навчає його базових навичок середньовічної медицини. Проте Роба прагне глибших знань про людське тіло та лікування хвороб. Дізнавшись про видатного перського вченого та лікаря Ібн Сіну (Авіценну), який викладає в медичній школі в Ісфахані, Роб вирушає у довгу та небезпечну подорож на Схід. Оскільки християнам заборонено навчатися в мусульманських закладах, він змушений видати себе за юдея, аби здобути омріяні знання у великого майстра." });
                Films?.Add(new Film { Name= "Амелі", FilmDirector= "Жан-П'єр Жене", Genre= "Мелодрама/Комедія", Year=2001, Poster= "Амелі.jpg", Description= "Дія фільму розгортається у Парижі. Головна героїня Амелі Пулен — дивакувата, самотня й надзвичайно спостережлива дівчина, яка бачить світ крізь призму власних фантазій. У дитинстві через помилковий діагноз батьків вона майже не спілкувалася з однолітками, тому створила власний внутрішній всесвіт. Одного дня, випадково знайшовши у своїй квартирі стару металеву коробочку з дитячими іграшками колишнього мешканця, вона вирішує повернути знахідку власнику. Побачивши, як цей вчинок змінює життя людини, Амелі знаходить своє покликання: вона починає таємно втручатися в життя інших парижан, допомагаючи їм знайти щастя, любов і гармонію, хоча сама довгий час не наважується влаштувати власне особисте життя." });
